// Broadcast resource.
// Ref: #/components/schemas/BroadcastResource
type BroadcastResource struct {
	// Unique identifier.
	ID EntityId `json:"id"`
	// Internal broadcast name.
	Name string `json:"name"`
	// The Channel the broadcast sends on, fixed when it was created.
	Channel BroadcastChannel `json:"channel"`
	// What the broadcast says, in the shape of its Channel.
	Content BroadcastContent `json:"content"`
	// Segment this broadcast goes to; null means all contacts. Once the broadcast leaves draft it holds a
	// copy of the segment's condition taken then, and this names the segment only as where its audience
	// came from.
	SegmentId OptNilEntityId `json:"segmentId"`
	// Lifecycle status. Broadcasts created here are always drafts.
	Status BroadcastStatus `json:"status"`
	// When the broadcast is scheduled to send.
	ScheduledAt OptNilTimestamp `json:"scheduledAt"`
	// The recipients the broadcast would take at the moment it was scheduled: its audience's contacts with
	// a destination on its Channel that is neither suppressed nor unsubscribed (ADR 0149). Answered by
	// Schedule only. It is the count at Schedule, not a promise: recipients are resolved at send time from
	// the condition copied then (ADR 0065).
	Recipients OptInt32 `json:"recipients"`
	// The recipients Cancel left unsent: those with no message when it landed (ADR 0150). A message
	// already handed to the provider goes out and is not counted. Answered by Cancel only.
	Unsent OptInt32 `json:"unsent"`
	// When the broadcast finished sending.
	SentAt OptNilTimestamp `json:"sentAt"`
	// When the broadcast failed.
	FailedAt OptNilTimestamp `json:"failedAt"`
	// When the broadcast was archived; null while it is kept. An archived broadcast is read-only until it
	// is unarchived.
	ArchivedAt OptNilTimestamp `json:"archivedAt"`
	// The revision of the state this answer shows (ADR 0119): an update, a change of its segment and
	// Schedule name it.
	Revision Revision `json:"revision"`
	// Creation timestamp.
	CreatedAt Timestamp `json:"createdAt"`
	// Last update timestamp.
	UpdatedAt Timestamp `json:"updatedAt"`
}

