// Delivery metadata of one outbound message; the rendered message is not included.
// Ref: #/components/schemas/ContactExportOutboundMessage
type ContactExportOutboundMessage struct {
	// Unique identifier.
	ID EntityId `json:"id"`
	// What kind of send produced the message.
	Kind string `json:"kind"`
	// Channel the message was sent over.
	Channel string `json:"channel"`
	// Address the message was sent to.
	Destination string `json:"destination"`
	// Every address a message rendered once for several went to (a Telegram message to the contact's
	// chats), `destination` among them; null for a message to one.
	Destinations OptNilStringArray `json:"destinations"`
	// Sending source.
	SendingSource OptNilString `json:"sendingSource"`
	// Sending domain.
	SendingDomain OptNilString `json:"sendingDomain"`
	// The provider's message id.
	ProviderMessageId OptNilString `json:"providerMessageId"`
	// Delivery status.
	Status string `json:"status"`
	// Why a skipped message was skipped.
	SkippedReason OptNilSkippedReason `json:"skippedReason"`
	// What a failed message failed with.
	Failure OptNilString `json:"failure"`
	// When the send was claimed.
	ClaimedAt Timestamp `json:"claimedAt"`
	// When the message was sent.
	SentAt OptNilTimestamp `json:"sentAt"`
	// When the provider first reported the message delivered.
	DeliveredAt OptNilTimestamp `json:"deliveredAt"`
	// When the provider first reported the message bounced.
	BouncedAt OptNilTimestamp `json:"bouncedAt"`
	// When the provider reported the message undelivered (SMS); a message delivered first is never
	// undelivered after.
	UndeliveredAt OptNilTimestamp `json:"undeliveredAt"`
	// The provider's error code of the undelivered report (Twilio's ErrorCode).
	UndeliveredCode OptNilString `json:"undeliveredCode"`
	// When the provider first reported a spam complaint about the message.
	ComplainedAt OptNilTimestamp `json:"complainedAt"`
	// When the contact first opened the message (a person, not a mail client).
	OpenedAt OptNilTimestamp `json:"openedAt"`
	// When the contact first clicked a link of the message (a person, not a mail client).
	ClickedAt OptNilTimestamp `json:"clickedAt"`
	// True when the message went through a Test inbox: captured, not delivered.
	Captured bool `json:"captured"`
	// Whether the message went out tracked: with an open pixel and its links rewritten, or its links made
	// Short tracked links (ADR 0120). False for a message no render decided (skipped before its render, or
	// not rendered yet).
	Tracked bool `json:"tracked"`
	// When a render decided whether the message goes out tracked; null for a message no render decided,
	// and for one sent before the moment was recorded, which went out tracked.
	TrackingDecidedAt OptNilTimestamp `json:"trackingDecidedAt"`
	// When the message's tracking was withdrawn (a refusal of the contact's, or the Workspace's default
	// turned to `dont_track`); null while it was not.
	TrackingWithdrawnAt OptNilTimestamp `json:"trackingWithdrawnAt"`
	// Broadcast that produced the message.
	BroadcastId OptNilEntityId `json:"broadcastId"`
	// Automation that produced the message.
	AutomationId OptNilEntityId `json:"automationId"`
	// Id of the automation Step that produced the message, the same in every version.
	AutomationStepId OptNilString `json:"automationStepId"`
	// Template the message was rendered from.
	TemplateId OptNilEntityId `json:"templateId"`
	// Creation timestamp.
	CreatedAt Timestamp `json:"createdAt"`
}

